import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from forma_a import P, armar  # noqa: E402
C=Path(__file__).resolve().parents[4]/'contenido'/'04-medio/examenes'
PTS={3:4,4:2,5:3,8:4,9:2,10:3,13:4,14:2,15:3,18:4,19:2,20:3,23:4,24:2,25:3}
Q=[]
def q(sec,en,ops,l,ex,oa):
    n=len(Q)+1; pts=PTS.get(n,1); tipo="Varias correctas" if len(l)>1 else "Alternativas"
    cab="**{n}.** " if pts==1 else f"**{{n}}.** ({tipo} — {pts} puntos) "
    Q.append(P(sec,cab,en,ops,l,ex,oa,{"pts":pts,"tipo":tipo}))
SEC=lambda r,oa,t,a,b: f"## SECCIÓN {r} — OA N°{oa}: {t}\n### (Preguntas {a} a {b})\n\n"
CASO=lambda t,preg: f"Lee el siguiente caso:\n\n*\"{t}\"*\n\n{preg}"
UNIR=lambda conceptos,defs: f"Une cada {conceptos[0]} con su {conceptos[1]}.\n\n{conceptos[2]}\n\n{defs}\n\n¿Qué combinación es correcta?"
q(SEC("I",1,"Institucionalidad democrática",1,5),"¿Qué órgano tiene la función de controlar que las leyes respeten la Constitución?",
 ["La Contraloría General de la República, que revisa los actos de la administración","*El Tribunal Constitucional","El Servicio Electoral, que administra los procesos electorales del país","La Corte de Apelaciones de cada región"],"b","El Tribunal Constitucional controla que las leyes y otras normas se ajusten a la Constitución; la Contraloría revisa la legalidad de los actos de la administración.","OA 1")
q("","¿Cuánto dura el período presidencial en Chile y puede el Presidente ser reelegido para el período inmediatamente siguiente?",
 ["*Cuatro años, sin reelección inmediata","Seis años, con una reelección inmediata","Cuatro años, con reelecciones ilimitadas","Ocho años, sin ninguna posibilidad de volver a postular"],"a","El período presidencial dura cuatro años y la Constitución no permite la reelección para el período inmediatamente siguiente.","OA 1")
q("","¿Cuáles de las siguientes afirmaciones son **verdaderas**? Marca **todas** las correctas.",
 ["La Cámara de Diputadas y Diputados fiscaliza los actos del gobierno.","El Presidente puede disolver el Congreso cuando este rechaza sus proyectos de ley.","El Senado resuelve las acusaciones constitucionales que presenta la Cámara de Diputadas y Diputados.","El concejo municipal fiscaliza la gestión del alcalde o alcaldesa."],"acd",
 "La Cámara fiscaliza al gobierno, el Senado resuelve las acusaciones constitucionales y el concejo municipal fiscaliza al alcalde; el Presidente no puede disolver el Congreso.","OA 1")
q("","¿Qué función cumple la Contraloría General de la República en la distribución del poder?",
 ["Dicta las leyes de la República junto con el Congreso Nacional y el Presidente","Elige a los jueces de la Corte Suprema mediante una votación popular cada cuatro años","Organiza todas las elecciones del país y proclama a las autoridades que resultan electas","*Controla la legalidad de los actos de la administración y fiscaliza el uso de los recursos públicos"],"d","La Contraloría es un órgano autónomo que controla la legalidad de los actos de la administración y fiscaliza el uso de los recursos públicos: limita el poder del Ejecutivo.","OA 1")
q("",CASO("Un alcalde quiere construir un estadio con fondos municipales. Para hacerlo, el concejo municipal debe aprobar el presupuesto, y la Contraloría puede revisar la legalidad del gasto. Un grupo de vecinos pide además una consulta ciudadana.","¿Qué afirmaciones explican correctamente cómo se distribuye y limita el poder en este caso? Marca **todas** las correctas."),
 ["El concejo municipal, al aprobar o rechazar el presupuesto, limita las decisiones del alcalde","La Contraloría puede controlar que el gasto se ajuste a la ley","El alcalde puede gastar los fondos municipales sin la aprobación de nadie","Los vecinos pueden participar mediante mecanismos como las consultas o los plebiscitos comunales"],"abd",
 "El concejo, la Contraloría y la participación vecinal limitan y equilibran las decisiones del alcalde; ningún alcalde puede gastar fondos municipales sin aprobación ni control.","OA 1")
q(SEC("II",3,"Desarrollo, políticas económicas y sustentabilidad",6,10),"¿Cuál de las siguientes decisiones corresponde a una **política monetaria**?",
 ["El Congreso aprueba un nuevo impuesto a las grandes fortunas","El gobierno aumenta el presupuesto de salud para el próximo año","*El Banco Central sube la tasa de interés para controlar la inflación","Un municipio construye una nueva plaza en un barrio de la comuna"],"c","La política monetaria la conduce el Banco Central, por ejemplo, subiendo o bajando la tasa de interés para controlar la inflación; los impuestos y el gasto son política fiscal.","OA 3")
q("","Un país busca diversificar su economía para depender menos de la exportación de cobre. ¿Qué medida es coherente con ese objetivo?",
 ["Aumentar solo la extracción de cobre para poder vender más toneladas cada año","Cerrar todas las empresas del país que no estén relacionadas con la minería","Prohibir las exportaciones de cualquier producto chileno que sea distinto del cobre","*Fomentar nuevas industrias, como las energías renovables y los servicios tecnológicos"],"d","Diversificar es desarrollar otros sectores productivos, como las energías renovables o los servicios tecnológicos, para no depender de un solo recurso.","OA 3")
q("",UNIR(("concepto","definición","(1) Inflación — (2) Producto Interno Bruto — (3) Crecimiento económico — (4) Desarrollo humano"),"(A) Valor de todos los bienes y servicios finales producidos en un país en un año.\n(B) Aumento sostenido y generalizado de los precios.\n(C) Mejora de la salud, la educación y los ingresos de las personas.\n(D) Aumento de la producción de un país a lo largo del tiempo."),
 ["*1-B, 2-A, 3-D, 4-C","1-A, 2-B, 3-C, 4-D","1-B, 2-D, 3-A, 4-C","1-C, 2-A, 3-D, 4-B"],"b","La inflación es el alza sostenida de precios (B); el PIB, el valor de lo producido en un año (A); el crecimiento, el aumento de la producción en el tiempo (D); y el desarrollo humano, la mejora en salud, educación e ingresos (C).","OA 3")
q("","Un proyecto minero promete muchos empleos, pero usaría grandes cantidades de agua en una zona afectada por la sequía. ¿Qué tensión del desarrollo muestra este caso?",
 ["*La tensión entre el crecimiento económico y la sustentabilidad ambiental y social de la zona","Ninguna tensión, porque los empleos siempre resuelven todos los problemas de una zona","La tensión entre dos empresas mineras que compiten por el mismo yacimiento de cobre","La tensión entre el Banco Central y el Congreso por la tasa de interés del país"],"a","El proyecto genera empleo (crecimiento), pero compromete un recurso escaso del que dependen otras personas: es la tensión entre crecimiento económico y sustentabilidad ambiental y social.","OA 3")
q("",CASO("Una comuna costera depende casi por completo de la pesca industrial. Ante la disminución de los peces, el municipio propone diversificar la economía con turismo y energías renovables, y abrir mesas de trabajo con la comunidad.","¿Qué afirmaciones sobre el desarrollo sustentable de esta comuna son correctas? Marca **todas** las correctas."),
 ["Diversificar la economía reduce la dependencia de un solo recurso natural","El desarrollo sustentable significa crecer sin límites, sin importar los recursos","Un desarrollo sustentable considera los efectos ambientales y sociales de las decisiones","La participación de la comunidad local puede mejorar la calidad de las decisiones"],"acd",
 "Diversificar, considerar los efectos ambientales y sociales y hacer participar a la comunidad son parte del desarrollo sustentable; crecer sin límites contradice esa idea.","OA 3")
q(SEC("III",4,"Derechos laborales",11,15),"¿Qué documento debe existir por escrito al comenzar una relación laboral y qué debe indicar?",
 ["Un finiquito, con el monto que se pagará al terminar el trabajo","Una boleta de honorarios, con el valor de cada hora trabajada","*Un contrato de trabajo, con las funciones, la jornada y la remuneración","Un certificado de antecedentes, con la dirección de la persona"],"c","El contrato de trabajo debe constar por escrito e indicar, entre otras cosas, las funciones, la jornada y la remuneración acordadas.","OA 4")
q("","¿Qué es el finiquito?",
 ["El documento que se firma al iniciar un trabajo, con las funciones del cargo","*El documento que pone término a la relación laboral y deja constancia de los pagos pendientes","La liquidación de sueldo que el trabajador recibe todos los meses junto con su pago","El reglamento interno de orden, higiene y seguridad que tiene cada empresa"],"b","El finiquito pone término a la relación laboral y deja constancia de los pagos pendientes, como vacaciones proporcionales o indemnizaciones.","OA 4")
q("",UNIR(("mecanismo de protección laboral","contenido","(1) Sindicato — (2) Negociación colectiva — (3) Seguro de cesantía — (4) Fuero maternal"),"(A) Proceso en que trabajadores y empleador acuerdan condiciones de trabajo.\n(B) Protección que impide despedir a una trabajadora embarazada sin autorización judicial.\n(C) Organización de trabajadores para defender sus intereses comunes.\n(D) Protección económica ante la pérdida del empleo."),
 ["*1-C, 2-A, 3-D, 4-B","1-A, 2-C, 3-B, 4-D","1-C, 2-D, 3-A, 4-B","1-B, 2-A, 3-D, 4-C"],"d","El sindicato es la organización de trabajadores (C); la negociación colectiva, el proceso para acordar condiciones (A); el seguro de cesantía protege ante la pérdida del empleo (D); y el fuero maternal impide despedir a una trabajadora embarazada sin autorización judicial (B).","OA 4")
q("","Un empleador paga las horas extraordinarias como si fueran horas normales, sin ningún recargo. ¿Qué evaluación es correcta?",
 ["*Vulnera el derecho a que las horas extraordinarias se paguen con un recargo legal; el trabajador puede reclamar ante la Inspección del Trabajo","Es correcto, porque una hora de trabajo vale siempre lo mismo, se trabaje dentro o fuera de la jornada acordada","Es correcto si el trabajador no reclamó en el momento, porque así aceptó tácitamente las condiciones del empleador","Solo es un problema si la empresa es muy grande, porque las empresas pequeñas no deben pagar horas extraordinarias"],"a","La ley exige pagar las horas extraordinarias con un recargo (al menos 50 % sobre el sueldo convenido); si no se paga, el trabajador puede reclamar ante la Inspección del Trabajo.","OA 4")
q("",CASO("Una repartidora trabaja diez horas diarias para una aplicación de reparto. No tiene contrato y la aplicación no cotiza por ella para la salud ni para la pensión.","¿Qué afirmaciones son correctas sobre su situación? Marca **todas** las correctas."),
 ["Como usa su propia bicicleta, no tiene ningún derecho laboral que reclamar","La falta de cotizaciones afecta su futura pensión y su acceso a la salud","En Chile existe una ley que regula el trabajo en plataformas digitales de servicios","Organizarse con otros trabajadores es una forma de defender sus derechos"],"bcd",
 "Sin cotizaciones se afectan su pensión y su salud; desde 2022 una ley regula el trabajo en plataformas digitales, y organizarse colectivamente es una forma de defender derechos. Usar su bicicleta no le quita sus derechos.","OA 4")
q(SEC("IV",5,"Libertad, igualdad y solidaridad",16,20),"Una ciudad garantiza el derecho a voto de todas las personas, pero varios locales de votación no tienen rampas y las personas en silla de ruedas no pueden entrar. ¿Qué tensión muestra este caso?",
 ["Entre la libertad de expresión de los vecinos y el derecho a la propiedad privada de los locales","Entre el Poder Judicial y el Poder Legislativo por el control de los locales de votación","Entre el voto voluntario y el voto obligatorio en las elecciones municipales de la ciudad","*Entre la igualdad formal ante la ley y la igualdad real de condiciones para ejercer un derecho"],"d","El derecho a votar existe en la ley (igualdad formal), pero sin rampas algunas personas no pueden ejercerlo (falta igualdad real de condiciones).","OA 5")
q("","Una empresa paga a sus trabajadoras un sueldo menor que a sus trabajadores hombres por realizar exactamente el mismo trabajo. ¿Qué evaluación es correcta?",
 ["*Vulnera el derecho a la igualdad de remuneraciones entre hombres y mujeres por un mismo trabajo","Es una decisión válida, porque cada empresa fija libremente los sueldos de su personal","Solo sería un problema si las trabajadoras tuvieran menos años de experiencia","Es correcto si las trabajadoras firmaron su contrato aceptando esa diferencia"],"a","La ley chilena establece el derecho a la igualdad de remuneraciones entre hombres y mujeres que realizan un mismo trabajo; pagar menos solo por el sexo es discriminación.","OA 5")
q("","¿Cuáles de las siguientes afirmaciones son **verdaderas**? Marca **todas** las correctas.",
 ["La igualdad significa tratar siempre a todas las personas exactamente igual, sin considerar sus diferencias.","La solidaridad se expresa, por ejemplo, en sistemas donde se aporta al bien común para apoyar a quienes más lo necesitan.","La libertad de una persona tiene como límite los derechos de las demás.","Las acciones afirmativas buscan corregir desigualdades que han afectado históricamente a ciertos grupos."],"bcd",
 "La solidaridad apoya a quienes más lo necesitan, la libertad tiene límites en los derechos ajenos y las acciones afirmativas corrigen desigualdades históricas; la igualdad no exige ignorar las diferencias.","OA 5")
q("","¿Qué ejemplo ilustra mejor el principio de **solidaridad** en una política pública?",
 ["Que cada persona pague por completo y en forma individual todos los servicios que usa","Que el Estado deje de financiar la educación y la salud de toda la población","*Un sistema de salud en que quienes tienen más recursos aportan para cubrir también a quienes tienen menos","Que solo las personas con mayores ingresos puedan acceder a los hospitales públicos"],"c","La solidaridad implica que quienes tienen más aporten para cubrir también a quienes tienen menos, como en un sistema de salud con financiamiento solidario.","OA 5")
q("",CASO("Un liceo recibe a estudiantes con discapacidad visual. Para que puedan aprender junto a sus compañeros, adapta los materiales al braille y al audio, y capacita a sus docentes.","¿Qué afirmaciones son correctas sobre las medidas del liceo? Marca **todas** las correctas."),
 ["Buscan asegurar la igualdad de oportunidades para aprender","Constituyen un privilegio injusto frente al resto de los estudiantes","Aplican el principio de inclusión en la educación","Muestran que la libertad de aprender requiere también condiciones materiales"],"acd",
 "Las adaptaciones buscan igualdad de oportunidades, aplican la inclusión y muestran que la libertad de aprender necesita condiciones materiales; no son un privilegio, sino una forma de equidad.","OA 5")
q(SEC("V",6,"Medios de comunicación y nuevas tecnologías",21,25),"¿Cuál de los siguientes ejemplos ilustra un **riesgo** de las redes sociales para la democracia?",
 ["Que la ciudadanía pueda informarse sobre las votaciones del Congreso en tiempo real","*La difusión masiva de noticias falsas que influyen en la opinión antes de una elección","Que los vecinos se organicen por internet para limpiar una plaza de su barrio","Que las autoridades publiquen sus agendas y gastos para que cualquiera los revise"],"b","Las noticias falsas que se difunden masivamente pueden engañar a la ciudadanía y alterar decisiones democráticas, como una elección: es un riesgo de las redes sociales.","OA 6")
q("","¿Qué es el ciberacoso?",
 ["*El hostigamiento reiterado a una persona por medios digitales","Una falla técnica en una red social que borra mensajes","El uso de internet para estudiar fuera del horario de clases","La venta de productos por aplicaciones de comercio electrónico"],"a","El ciberacoso es el hostigamiento reiterado a una persona a través de medios digitales (mensajes, publicaciones, imágenes), que daña su dignidad y su bienestar.","OA 6")
q("",UNIR(("fenómeno","descripción","(1) Noticia falsa — (2) Burbuja de filtro — (3) Deepfake — (4) Verificación de datos"),"(A) Video o audio manipulado con inteligencia artificial para imitar a una persona real.\n(B) Contenido falso presentado con apariencia de noticia.\n(C) Contrastar una afirmación con fuentes confiables antes de darla por cierta.\n(D) Efecto de los algoritmos que muestran solo contenidos parecidos a lo que ya pensamos."),
 ["*1-B, 2-D, 3-A, 4-C","1-A, 2-B, 3-C, 4-D","1-B, 2-C, 3-D, 4-A","1-D, 2-B, 3-A, 4-C"],"c","La noticia falsa es contenido falso con apariencia de noticia (B); la burbuja de filtro, el efecto de los algoritmos (D); el deepfake, un video o audio manipulado con IA (A); y la verificación, contrastar con fuentes confiables (C).","OA 6")
q("","Antes de compartir una noticia muy sorprendente que llegó por una red social, ¿qué práctica es la más responsable?",
 ["Compartirla de inmediato, porque si es viral seguramente es verdadera","Compartirla solo con los amigos más cercanos, sin revisar nada","Agregarle un comentario indignado para que llegue a más personas","*Revisar la fuente y la fecha, y contrastarla con otros medios confiables"],"d","Antes de compartir conviene verificar quién publicó la noticia, cuándo y si otros medios confiables la confirman: así se evita difundir desinformación.","OA 6")
q("",CASO("Durante una campaña electoral circula en redes sociales un video en que un candidato parece decir frases ofensivas que, según su equipo, nunca pronunció.","¿Qué afirmaciones son correctas frente a este caso? Marca **todas** las correctas."),
 ["El video podría ser un deepfake, creado con inteligencia artificial","Compartirlo sin verificarlo puede contribuir a la desinformación","Como el video es viral, necesariamente es verdadero","Existen medios de verificación de datos que pueden ayudar a confirmar si es real"],"abd",
 "El video podría estar manipulado con IA, compartirlo sin verificar puede desinformar y hay medios de verificación que ayudan a confirmarlo; que sea viral no lo hace verdadero.","OA 6")
